mapper.select:
select *
from contract_supplier_invoice
where bool_delete_enum = 0

    and order_id = #{orderId}


    and property_type & #{propertyType} > 0


    and supplier_id = #{supplierId}


    and audit_status = #{auditStatus}


    and date(receive_invoice_date) >= date(#{startDate})


    and date(receive_invoice_date) <= date(#{endDate})

    order by audit_status, id desc

choose.when:
SELECT IFNULL(SUM(invoice_amount), 0)
FROM contract_supplier_invoice as csi
    INNER JOIN scm_purchase_order AS spo on csi.order_id = spo.id AND spo.bool_delete_enum = 0
WHERE  csi.bool_delete_enum = 0
AND  csi.audit_status = 2
AND  csi.property_type = 1

    AND csi.order_id = #{orderId}


    AND csi.supplier_id = #{supplierId}


    AND csi.branch_company_id = #{branchCompanyId}

SELECT IFNULL(SUM(invoice_amount), 0) FROM contract_supplier_invoice WHERE bool_delete_enum = 0 AND audit_status = 2 AND property_type = 2
AND supplier_id = #{supplierId}
AND branch_company_id = #{branchCompanyId}

mapper.select:
SELECT
IFNULL(SUM(csi.invoice_amount),0)
FROM contract_supplier_invoice AS csi
INNER JOIN scm_purchase_order AS spo ON csi.property_type = 1 AND csi.order_id = spo.id AND spo.bool_delete_enum = 0
WHERE csi.bool_delete_enum = 0
AND csi.audit_status = 2

    AND csi.supplier_id = #{supplierId}


   AND spo.create_time >= #{startDate}


   AND spo.create_time <= #{endDate}
